{"file_path": "/private/tmp/topic4-sessions/20260913T113923Z-devloop-no-note.SGaU/session/evaluation/gate/fetch-resource.mjs", "content": "/**
 * Fetch one team skill's resource file into local bytes.
 *
 * A skill is more than its SKILL.md: the manifest lists resource files
 * (scripts, fixtures, notes) living in the same storage directory. The bridge
 * exposes them through `files/read`, which returns a JSON envelope:
 *
 *   { code, message, data: { path, content, encoding, size_bytes, mime_type, version } }
 *
 * `content` is the file body as a string; `encoding` says how to read it —
 * `base64` for binary, anything else as UTF-8. So the caller gets a Buffer and
 * can write it straight to disk, no re-encoding on the way.
 *
 * Two things this deliberately does *not* do:
 *
 *   - It does not treat an empty body as an error. An empty resource is a legal
 *     file, and the `data.content` for it is the empty string — decoding that
 *     yields a zero-byte Buffer, which is exactly what should land on disk.
 *   - It does not swallow the upstream error envelope. A non-zero `code` means
 *     the bridge refused (not visible to this caller, missing path, wrong
 *     version, …); the envelope's `message` is the only useful thing in that
 *     response, so it is rethrown verbatim.
 *
 * The transport is injectable so the decoding can be tested without a running
 * stack: pass `fetcher` to stand in for `globalThis.fetch`, omit it to use the
 * real one.
 *
 * Usage:
 *   const bytes = await fetchResource({ skillId, path: "scripts/run.sh", bridgeBase });
 */

export async function fetchResource({ skillId, path, bridgeBase, fetcher = globalThis.fetch }) {
  if (!skillId) throw new Error("fetchResource: skillId is required");
  if (!path) throw new Error("fetchResource: path is required");
  if (!bridgeBase) throw new Error("fetchResource: bridgeBase is required");

  const url = `${String(bridgeBase).replace(/\/+$/, "")}/files/read`;
  const response = await fetcher(url, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ skill_id: skillId, path }),
  });

  const envelope = await response.json();
  if (!envelope || envelope.code !== 0) {
    throw new Error(envelope?.message ?? `files/read failed with code ${envelope?.code}`);
  }

  const { content = "", encoding } = envelope.data ?? {};
  return encoding === "base64" ? Buffer.from(content, "base64") : Buffer.from(content, "utf-8");
}
"}

{"file_path": "/private/tmp/topic4-sessions/20260913T113923Z-devloop-no-note.SGaU/session/evaluation/gate/fetch-resource.test.mjs", "content": "import { test } from "node:test";
import assert from "node:assert/strict";
import { Buffer } from "node:buffer";
import { fetchResource } from "./fetch-resource.mjs";

const BRIDGE = "http://127.0.0.1:8096/skill-bridge/v3/skill";

/** A fetcher that records its call and answers with the given JSON envelope. */
function stub(envelope, { onCall } = {}) {
  return async (url, init) => {
    onCall?.(url, init);
    return { json: async () => envelope };
  };
}

test("returns the resource as raw bytes and posts skill_id + path to files/read", async () => {
  let seen;
  const bytes = await fetchResource({
    skillId: "skl-a", path: "scripts/run.sh", bridgeBase: BRIDGE,
    fetcher: stub({ code: 0, message: "ok", data: { content: "echo hi\n", encoding: "utf-8" } },
      { onCall: (url, init) => { seen = { url, init }; } }),
  });
  assert.deepEqual(bytes, Buffer.from("echo hi\n", "utf-8"));
  assert.equal(seen.url, `${BRIDGE}/files/read`);
  assert.equal(seen.init.method, "POST");
  assert.deepEqual(JSON.parse(seen.init.body), { skill_id: "skl-a", path: "scripts/run.sh" });
});

test("decodes base64 content back to the original bytes", async () => {
  const original = Buffer.from([0x00, 0xff, 0x10, 0x80]);
  const bytes = await fetchResource({
    skillId: "skl-a", path: "assets/logo.bin", bridgeBase: BRIDGE,
    fetcher: stub({ code: 0, data: { content: original.toString("base64"), encoding: "base64" } }),
  });
  assert.deepEqual(bytes, original);
});

test("an empty resource is a zero-byte Buffer, not an error", async () => {
  for (const encoding of ["utf-8", "base64", undefined]) {
    const bytes = await fetchResource({
      skillId: "skl-a", path: "notes/empty.md", bridgeBase: BRIDGE,
      fetcher: stub({ code: 0, data: { content: "", encoding } }),
    });
    assert.equal(Buffer.isBuffer(bytes), true);
    assert.equal(bytes.length, 0);
  }
  // a missing data/content field is the same as an empty file
  const missing = await fetchResource({
    skillId: "skl-a", path: "notes/empty.md", bridgeBase: BRIDGE,
    fetcher: stub({ code: 0, data: {} }),
  });
  assert.equal(missing.length, 0);
});

test("a non-zero code throws the envelope's message", async () => {
  await assert.rejects(
    fetchResource({
      skillId: "skl-a", path: "scripts/run.sh", bridgeBase: BRIDGE,
      fetcher: stub({ code: 40401, message: "SKILL_NOT_FOUND: skill does not exist" }),
    }),
    (err) => {
      assert.ok(err instanceof Error);
      assert.equal(err.message, "SKILL_NOT_FOUND: skill does not exist");
      return true;
    },
  );
});

test("trailing slashes on bridgeBase do not double up", async () => {
  let seen;
  await fetchResource({
    skillId: "skl-a", path: "p", bridgeBase: `${BRIDGE}/`,
    fetcher: stub({ code: 0, data: { content: "x" } }, { onCall: (url) => { seen = url; } }),
  });
  assert.equal(seen, `${BRIDGE}/files/read`);
});

test("falls back to globalThis.fetch when no fetcher is injected", async () => {
  const real = globalThis.fetch;
  let called = null;
  globalThis.fetch = async (url, init) => {
    called = url;
    return { json: async () => ({ code: 0, data: { content: "ok" } }) };
  };
  try {
    const bytes = await fetchResource({ skillId: "skl-a", path: "p", bridgeBase: BRIDGE });
    assert.deepEqual(bytes, Buffer.from("ok", "utf-8"));
    assert.equal(called, `${BRIDGE}/files/read`);
  } finally {
    globalThis.fetch = real;
  }
});
"}

freshness.description:
Filter search results by time range. Supports d[N], m[N], and y[N] for the last N calendar days, months, and years:
- d[N]: N is an integer from 1 to 30;
- m[N]: N is an integer from 1 to 12;
- y[N]: N is an integer from 1 to 5.

N may be omitted and defaults to 1. The current partial calendar unit counts as 1. For example, d1 means today, m1 means the current month to date, and y1 means the current year to date. Omit this parameter to disable time filtering.

